import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:booking/core/theme/app_theme.dart';
import 'package:booking/navigation/app_router.dart';
import 'package:booking/widgets/network_overlay.dart';
import 'package:booking/data/mock_data.dart';
import 'package:booking/services/auth_service.dart';
import 'package:booking/firebase_options.dart';
// ⚠️  firebase_options.dart is generated by FlutterFire CLI.
// Run: dart pub global activate flutterfire_cli
//      flutterfire configure
// Then un-comment the import below and remove this comment.

// ============================================================
// Main Entry Point — Movix Movie Booking App
// Initialisation order:
//   1. WidgetsFlutterBinding.ensureInitialized()
//   2. Firebase.initializeApp()  ← exits gracefully on failure
//   3. MockData.loadData()       ← SharedPreferences data (unchanged)
//   4. AuthService.startObserving() ← app-resume revalidation
//   5. runApp(MyApp())
// ============================================================

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // ── Firebase initialisation ──────────────────────────────────────────────
  // If firebase_options.dart has not been generated yet (run flutterfire
  // configure first), this will throw. Show a graceful error screen instead
  // of a crash.
  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,  // ← uncomment after flutterfire configure
    );
  } catch (e) {
    // Firebase init failed — likely because firebase_options.dart has not
    // been generated yet, or google-services.json is missing.
    runApp(_FirebaseErrorApp(message: e.toString()));
    return;
  }

  await MockData.loadData();

  // Register lifecycle observer for app-resume profile revalidation.
  AuthService.instance.startObserving();

  runApp(const MyApp());
}

// ── Main App ─────────────────────────────────────────────────────────────────
class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Movix',
      debugShowCheckedModeBanner: false,
      theme: AppTheme.lightTheme,
      // The global navigator key allows AuthService to navigate (e.g. on
      // app-resume revalidation) without requiring a BuildContext.
      navigatorKey: appNavigatorKey,
      initialRoute: AppRouter.splash,
      onGenerateRoute: AppRouter.generateRoute,
      builder: (context, child) {
        return NetworkOverlay(child: child!);
      },
    );
  }
}

// ── Firebase init error screen ────────────────────────────────────────────────
// Shown if Firebase.initializeApp() fails.
// Most likely cause: flutterfire configure has not been run, or
// google-services.json is missing from android/app/.
class _FirebaseErrorApp extends StatelessWidget {
  final String message;
  const _FirebaseErrorApp({required this.message});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      theme: ThemeData.dark(),
      home: Scaffold(
        backgroundColor: Colors.black,
        body: Center(
          child: Padding(
            padding: const EdgeInsets.all(32),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Icon(Icons.warning_amber_rounded,
                    color: Colors.amber, size: 56),
                const SizedBox(height: 24),
                const Text(
                  'Firebase Initialisation Failed',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                  ),
                  textAlign: TextAlign.center,
                ),
                const SizedBox(height: 12),
                const Text(
                  'Run `flutterfire configure` to generate firebase_options.dart '
                  'and ensure google-services.json is in android/app/.',
                  style: TextStyle(color: Colors.grey, fontSize: 13, height: 1.5),
                  textAlign: TextAlign.center,
                ),
                const SizedBox(height: 20),
                Text(
                  message,
                  style: const TextStyle(color: Colors.red, fontSize: 11),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
